sys_ws_operation.operation_script:
(function process(request, response) {
  var body = {};
  try { body = JSON.parse(request.body.dataString); } catch (e) {
    response.setStatus(400);
    response.setBody({ result: { success: false, error: "Invalid request body" } });
    return;
  }
  var sysId = body.production_order_id;
  if (!sysId) {
    response.setStatus(400);
    response.setBody({ result: { success: false, error: "production_order_id is required" } });
    return;
  }
  var scheduler = new x_2056099_indust_0.ProductionScheduler();
  var result = scheduler.createDraftSchedule(sysId);
  if (!result.success) {
    response.setStatus(400);
  }
  response.setBody({ result: result });
})(request, response);
